import {salaryProgression,formatSalary} from './salary-progression.js?v=0.31.0';
import {escapeHTML as h} from './model.js?v=0.31.0';
export function salaryEvidenceLabel(stage){return !stage?'Pay estimate':stage.evidence==='official_entry_proxy'?'Estimated starting pay':stage.evidence==='employer_step_carried'?`${stage.sourceYears}-year step carried forward`:stage.estimate?'Planning estimate':stage.evidence==='employer_residency'?'Published residency example':stage.evidence==='employer_apprenticeship'?'Published apprenticeship example':stage.evidence==='employer_academy'?'Published academy pay':'Published employer pay example';}
export function salaryLifestyleLink(id,stage='entry',from='career'){return `<a class="salary-lifestyle-link" href="#/salary/${h(id)}/${h(stage)}?from=${['career','guided-career','income','plan','careers'].includes(from)?from:'career'}" aria-label="Lifestyle this salary supports · ${h(stage==='entry'?'entry level':stage==='residency'?'first-year resident':stage==='apprenticeship'?'first-period apprentice':stage==='academy'?'paid academy':stage.replace('year','')+' years')}">See the lifestyle →</a>`;}
export function salaryPanel(careerOrId,{stage='entry',interactive=false,from='career'}={}){
 const p=salaryProgression(careerOrId);if(!p)return '';const entry=p.stages[0],training=p.paidTraining;
 const stageCard=s=>`<article class="salary-stage ${s.key===stage?'selected':''}"><span>${h(s.label)}</span><b>${formatSalary(s.amount)}</b><span>${h(salaryEvidenceLabel(s))}</span>${salaryLifestyleLink(p.careerId,s.key,from)}${interactive?`<button class="button secondary salary-stage-select" data-action="guide-salary" data-id="${s.key}" aria-pressed="${s.key===stage}">Use this pay</button>`:''}</article>`;
 const timeNote=p.careerId==='police'?'Published service steps are used for planning; the 5- and 20-year cards carry earlier source steps.':p.method==='published_employer_schedule'?'Current new-hire placement example; future pay varies.':'Later amounts are planning estimates, not measured salaries at exact years or guaranteed raises.';
 const modelNote=p.careerId==='firefighter'?'Starting pay is Austin Fire’s published post-academy amount. Later scenarios use the local occupation benchmark, with starting pay as their minimum.':p.entryProxy?'Starting pay uses TWC’s mean of the lowest-paid third, an entry proxy rather than observed first-job pay.':'Starting pay uses a modeled local-wage estimate.';
 return `<section class="salary-panel" id="career-pay" data-coverage="earnings">${training&&stage===training.stageKey?'<p class="plan-pay-stage"><strong>My Plan uses paid training · '+formatSalary(training.amount)+' / year</strong></p>':''}<div class="salary-intro"><div><span class="overline">ENTRY-LEVEL PAY · BEFORE TAX</span><div class="salary-headline">${formatSalary(entry.amount)}<span>/ year</span></div><p class="salary-basis">${h(salaryEvidenceLabel(entry))} · ${p.geography?.startsWith('Dallas')?'Dallas source for Austin planning':p.geography?.startsWith('Houston')?'Houston source for Austin planning':'Austin area'}</p>${salaryLifestyleLink(p.careerId,'entry',from)}${interactive?`<button class="button secondary" data-action="guide-salary" data-id="entry" aria-pressed="${stage==='entry'}">Use starting pay</button>`:''}</div>${training?`<aside class="paid-training"><span>${training.stageKey==='residency'?'Paid residency':training.stageKey==='apprenticeship'?'Paid apprenticeship':'Paid academy'} comes first</span><strong>${formatSalary(training.amount)} / year</strong><p>${h(training.label||training.stageKey)}</p>${salaryLifestyleLink(p.careerId,training.stageKey,from)}${training.steps?'<details class="more-info"><summary>Three residency years</summary>'+training.steps.map(x=>'<p>'+h(x.label)+' · '+formatSalary(x.amount)+'</p>').join('')+'</details>':''}<a href="${h(training.sourceURL)}" target="_blank" rel="noopener">Published training pay ↗</a></aside>`:''}</div>${p.entryContext?'<p>'+h(p.entryContext)+'</p>':''}<div class="salary-timeline" aria-label="Pay comparisons by experience">${p.stages.slice(1).map(stageCard).join('')}</div><p>Years start once you finish the required training.${p.paidTraining?' Paid training comes before this.':''} ${h(timeNote)}</p>${p.variableHours?'<p>Fewer paid hours means lower annual income. Compare part-time and full-time work in the lifestyle view.</p>':''}<details class="more-info"><summary>More info · salary sources</summary><div><p>${h(p.geography)} · ${h(p.referencePeriod)}. These figures show employee pay, not a business’s sales. Source years are preserved; future inflation and promotions are not added.</p>${p.sharedWageScope?'<p>'+h(p.sharedWageScope)+'</p>':''}${p.method!=='published_employer_schedule'?'<p>'+h(modelNote)+' Later planning amounts move 45%, 75%, and 100% of the gap toward the occupation’s experienced-wage benchmark, subject to the starting-pay floor and local wage bounds. TWC’s experienced wage is the mean of the upper-paid two-thirds; where suppressed, the sourced local median is used. These fractions are planning assumptions, not a fitted experience-year series.</p>':''}${p.stablePay?'<p>Later rounded amounts are similar because the wage benchmark or starting-pay floor is close across these stages. No raise is added just to make the chart rise.</p>':''}${p.confidence==='low'?'<p>Five postings cannot establish typical pay or growth by experience. Use the independent-work budget to explore actual receipts and expenses.</p>':''}${training?.referencePeriod?'<p>Paid training source: '+h(training.referencePeriod)+(training.checkedAt?' · checked '+h(training.checkedAt):'')+'.</p>':''}${p.notes.map(n=>'<p>'+h(n)+'</p>').join('')}<ul>${p.sources.map(s=>`<li><a href="${h(s.url)}" target="_blank" rel="noopener">${h(s.title||s.publisher)} ↗</a> · ${h(s.publisher)}${s.checkedAt?' · checked '+h(s.checkedAt):''}${s.referencePeriod?' · '+h(s.referencePeriod):''}${s.role?'<p>'+h(s.role)+'</p>':''}</li>`).join('')}</ul></div></details></section>`;
}
